import type { FtrProviderContext } from '../ftr_provider_context';

// Entry point for the product-docs artifact generation pipeline
// (generate_artifacts.config.ts). Security Labs artifacts are generated by the
// dedicated generate_security_labs_artifacts.config.ts, which loads
// `./security_labs` directly, so the product-docs pipeline stays decoupled from
// the Security Labs GitHub fetch.
// eslint-disable-next-line import/no-default-export
export default function ({ loadTestFile }: FtrProviderContext) {
  describe('Gen AI artifacts', function () {
    loadTestFile(require.resolve('./product_docs'));
  });
}
